def transform(grid):
    # Infer the diagonal period and color for each residue from the painted
    # down-right diagonals; fill the periodic diagonal tiling.
    h, w = len(grid), len(grid[0])
    known = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                known[c-r] = v
    # Find the smallest period consistent with all observed diagonal offsets.
    offsets = list(known)
    period = None
    for p in range(1, h+w):
        residues = {}
        ok = True
        for d,v in known.items():
            k=d%p
            if k in residues and residues[k]!=v:
                ok=False; break
            residues[k]=v
        if ok and len(residues)==p:
            period=p; break
    if period is None:
        period=max(1, len(known))
    vals={d%period:v for d,v in known.items()}
    # Unobserved residues interpolate cyclically between nearest known diagonals.
    # For ARC stripe encodings, observed residues cover the cycle.
    for r in range(h):
        for c in range(w):
            k=(c-r)%period
            if k in vals: grid[r][c]=vals[k]
    return [row[:] for row in grid]
