def transform(grid):
    """Expand the observed down-right diagonal stripe pattern to the whole grid."""
    h, w = len(grid), len(grid[0])
    known = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value:
                known[c - r] = value

    # Find the smallest period consistent with all painted diagonals, requiring
    # every phase in the period to have an observed color.
    period = None
    for p in range(1, h + w):
        phases = {}
        for offset, value in known.items():
            phase = offset % p
            if phase in phases and phases[phase] != value:
                break
            phases[phase] = value
        else:
            if len(phases) == p:
                period = p
                break

    if period is not None:
        phases = {offset % period: value for offset, value in known.items()}
        return [[phases[(c - r) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
